//Do not modify this file, it is automatically generated by the ConfigTool.
//源表：quick_message.xlsx（快捷操作表）
#pragma warning disable 8981

using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<int, quick_message> quick_messageData;
        public quick_message Getquick_messageConfig(int key)
        {
            return ConfigBinary.Require(quick_messageData, key, "quick_message");
        }
        private void Loadquick_messageConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("quick_message"))
            {
                int count = r.ReadInt32();
                quick_messageData = new Dictionary<int, quick_message>(count);
                for (int i = 0; i < count; i++)
                {
                    quick_message row;
                    row.key = r.ReadInt32();
                    row.name = ConfigBinary.ReadString(r);
                    row.uiText = ConfigBinary.ReadString(r);
                    row.chatText = ConfigBinary.ReadString(r);
                    row.markerDuration = r.ReadInt32();
                    quick_messageData.Add(row.key, row);
                }
            }
        }
    }
    public struct quick_message
    {
        public int key;  // 主键
        public string name;  // 使用说明：快捷指令在 UI 里的名字
        public string uiText;  // UI文本：悬停说明，富文本
        public string chatText;  // 聊天内容：发到聊天频道的文本
        public int markerDuration;  // 点位显示时长：小地图点位显示的秒数，0 = 不显示
    }
}
